CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL CHECK(length(display_name)<=256), blocked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), last_active_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE telegram_accounts (telegram_id bigint PRIMARY KEY CHECK(telegram_id>0), user_id uuid NOT NULL UNIQUE REFERENCES users(id), username text NOT NULL DEFAULT '');
CREATE TABLE platform_admins (user_id uuid PRIMARY KEY REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY CHECK(length(token_hash)=64), user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_replays (digest text PRIMARY KEY, expires_at timestamptz NOT NULL);
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), owner_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX workspaces_owner ON workspaces(owner_id);
CREATE TABLE roles (key text PRIMARY KEY);
CREATE TABLE permissions (key text PRIMARY KEY);
CREATE TABLE role_permissions (role_key text REFERENCES roles(key), permission_key text REFERENCES permissions(key), PRIMARY KEY(role_key,permission_key));
CREATE TABLE workspace_members (workspace_id uuid REFERENCES workspaces(id), user_id uuid REFERENCES users(id), role_key text NOT NULL REFERENCES roles(key), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id));
CREATE INDEX workspace_members_user ON workspace_members(user_id);
CREATE TABLE plans (key text PRIMARY KEY, name text NOT NULL, active boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE features (key text PRIMARY KEY, name_key text NOT NULL, permission_key text NOT NULL REFERENCES permissions(key));
CREATE TABLE feature_flags (feature_key text PRIMARY KEY REFERENCES features(key), enabled boolean NOT NULL DEFAULT false, rollout_status text NOT NULL DEFAULT 'OFF' CHECK(rollout_status IN ('ON','OFF','BETA')), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plugins (key text PRIMARY KEY, name_key text NOT NULL, version text NOT NULL, status text NOT NULL CHECK(status IN('ENABLED','DISABLED','BETA')), required_feature text NOT NULL REFERENCES features(key), configuration_schema jsonb NOT NULL DEFAULT '{"type":"object","additionalProperties":false}', permissions jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plugin_dependencies (plugin_key text REFERENCES plugins(key), dependency_key text REFERENCES plugins(key), CHECK(plugin_key<>dependency_key), PRIMARY KEY(plugin_key,dependency_key));
CREATE TABLE plan_entitlements (plan_key text REFERENCES plans(key), feature_key text REFERENCES features(key), enabled boolean NOT NULL, limit_value bigint CHECK(limit_value>=0), PRIMARY KEY(plan_key,feature_key));
CREATE TABLE plan_plugin_entitlements (plan_key text REFERENCES plans(key), plugin_key text REFERENCES plugins(key), enabled boolean NOT NULL, PRIMARY KEY(plan_key,plugin_key));
CREATE TABLE subscriptions (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), plan_key text NOT NULL REFERENCES plans(key), previous_plan_key text REFERENCES plans(key), expires_at timestamptz, scheduled_plan_key text REFERENCES plans(key), scheduled_at timestamptz, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((scheduled_plan_key IS NULL)=(scheduled_at IS NULL)), CHECK((previous_plan_key IS NULL)=(expires_at IS NULL)));
CREATE TABLE subscription_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), actor_id uuid NOT NULL REFERENCES users(id), old_plan text NOT NULL, new_plan text NOT NULL, reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000), effective_at timestamptz NOT NULL, expires_at timestamptz, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_entitlement_overrides (workspace_id uuid REFERENCES workspaces(id), feature_key text REFERENCES features(key), enabled boolean NOT NULL, limit_value bigint CHECK(limit_value>=0), expires_at timestamptz, reason text NOT NULL, PRIMARY KEY(workspace_id,feature_key));
CREATE TABLE temporary_grants (workspace_id uuid REFERENCES workspaces(id), feature_key text REFERENCES features(key), enabled boolean NOT NULL DEFAULT true, limit_value bigint CHECK(limit_value>=0), expires_at timestamptz NOT NULL, reason text NOT NULL, PRIMARY KEY(workspace_id,feature_key));
CREATE TABLE usage_counters (workspace_id uuid REFERENCES workspaces(id), feature_key text REFERENCES features(key), used bigint NOT NULL DEFAULT 0 CHECK(used>=0), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, CHECK(period_end>period_start), PRIMARY KEY(workspace_id,feature_key,period_start));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id), actor_id uuid REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, correlation_id text NOT NULL, old_summary jsonb NOT NULL DEFAULT '{}', new_summary jsonb NOT NULL DEFAULT '{}', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_workspace_time ON audit_logs(workspace_id,created_at DESC);
CREATE TABLE wallet_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), asset text NOT NULL CHECK(asset IN('IRR','USD','USDT_TON','TON','XTR')), kind text NOT NULL CHECK(kind IN('WALLET','CLEARING')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,asset,kind), UNIQUE(id,workspace_id,asset));
CREATE TABLE ledger_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), asset text NOT NULL, transaction_type text NOT NULL CHECK(transaction_type IN('ADMIN_ADJUSTMENT','PAYMENT','PURCHASE','REFUND')), status text NOT NULL DEFAULT 'POSTED' CHECK(status='POSTED'), reference text NOT NULL, idempotency_key text NOT NULL, fingerprint text NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000), correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id,asset));
CREATE TABLE ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), transaction_id uuid NOT NULL, account_id uuid NOT NULL, asset text NOT NULL, amount_atomic bigint NOT NULL CHECK(amount_atomic<>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(transaction_id,workspace_id,asset) REFERENCES ledger_transactions(id,workspace_id,asset), FOREIGN KEY(account_id,workspace_id,asset) REFERENCES wallet_accounts(id,workspace_id,asset));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE TABLE payment_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), asset text NOT NULL CHECK(asset IN('IRR','USD','USDT_TON','TON','XTR')), amount_atomic bigint NOT NULL CHECK(amount_atomic>0), provider text NOT NULL, recipient text NOT NULL, quote_snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN('PENDING','CONFIRMED','EXPIRED','FAILED')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), UNIQUE(id,workspace_id));
CREATE TABLE payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), intent_id uuid NOT NULL, provider text NOT NULL, external_reference text NOT NULL, asset text NOT NULL, amount_atomic bigint NOT NULL CHECK(amount_atomic>0), status text NOT NULL CHECK(status='CONFIRMED'), ledger_transaction_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,external_reference), FOREIGN KEY(intent_id,workspace_id) REFERENCES payment_intents(id,workspace_id), FOREIGN KEY(ledger_transaction_id,workspace_id,asset) REFERENCES ledger_transactions(id,workspace_id,asset), UNIQUE(id,workspace_id));
CREATE TABLE payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), intent_id uuid NOT NULL, provider text NOT NULL, status text NOT NULL CHECK(status IN('PENDING','FAILED','VERIFIED')), error_code text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(intent_id,workspace_id) REFERENCES payment_intents(id,workspace_id));
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), payment_id uuid NOT NULL, asset text NOT NULL, amount_atomic bigint NOT NULL CHECK(amount_atomic>0), reason text NOT NULL, idempotency_key text NOT NULL, ledger_transaction_id uuid NOT NULL, status text NOT NULL CHECK(status IN('REQUESTED','CONFIRMED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,idempotency_key), FOREIGN KEY(payment_id,workspace_id) REFERENCES payment_transactions(id,workspace_id), FOREIGN KEY(ledger_transaction_id,workspace_id,asset) REFERENCES ledger_transactions(id,workspace_id,asset));
CREATE TABLE financial_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), ledger_transaction_id uuid NOT NULL, asset text NOT NULL, amount_atomic bigint NOT NULL CHECK(amount_atomic<>0), actor_id uuid NOT NULL REFERENCES users(id), reason text NOT NULL, correlation_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(ledger_transaction_id,workspace_id,asset) REFERENCES ledger_transactions(id,workspace_id,asset));
CREATE TABLE invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), asset text NOT NULL CHECK(asset IN('IRR','USD','XTR')), amount_atomic bigint NOT NULL CHECK(amount_atomic>0), status text NOT NULL CHECK(status IN('DRAFT','ISSUED','PAID','VOID')), reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,reference));
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id), subject text NOT NULL, event_type text NOT NULL, payload jsonb NOT NULL, correlation_id text NOT NULL, published_at timestamptz, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE inbox_events (consumer text NOT NULL, event_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer,event_id));
CREATE TABLE dead_letter_events (consumer text NOT NULL, event_id uuid NOT NULL, error_code text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer,event_id));
CREATE TABLE telegram_updates (bot_key text NOT NULL, update_id bigint NOT NULL, user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(bot_key,update_id));
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'append-only record'; END $$;
CREATE TRIGGER ledger_no_mutation BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER entries_no_mutation BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_no_mutation BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER adjustments_no_mutation BEFORE UPDATE OR DELETE ON financial_adjustments FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER subscription_events_no_mutation BEFORE UPDATE OR DELETE ON subscription_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION enforce_ledger_balance() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE tid uuid; n bigint; total numeric; bad boolean;
BEGIN
 tid:=CASE WHEN TG_TABLE_NAME='ledger_transactions' THEN NEW.id ELSE NEW.transaction_id END;
 SELECT count(*),COALESCE(sum(amount_atomic),0) INTO n,total FROM ledger_entries WHERE transaction_id=tid;
 IF n<2 OR total<>0 THEN RAISE EXCEPTION 'unbalanced ledger transaction'; END IF;
 SELECT EXISTS(SELECT 1 FROM wallet_accounts a JOIN ledger_entries e ON e.account_id=a.id WHERE a.kind='WALLET' AND a.id IN(SELECT account_id FROM ledger_entries WHERE transaction_id=tid) GROUP BY a.id HAVING sum(e.amount_atomic)<0) INTO bad;
 IF bad THEN RAISE EXCEPTION 'insufficient wallet balance'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER balanced_transaction AFTER INSERT ON ledger_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_ledger_balance();
CREATE CONSTRAINT TRIGGER balanced_entry AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_ledger_balance();
CREATE FUNCTION lock_ledger_account() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM 1 FROM wallet_accounts WHERE id=NEW.account_id FOR UPDATE; RETURN NEW; END $$;
CREATE TRIGGER serialize_entry BEFORE INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION lock_ledger_account();
CREATE VIEW wallet_balances WITH(security_invoker=true) AS SELECT a.id,a.workspace_id,a.asset,COALESCE(sum(e.amount_atomic),0)::text AS balance_atomic FROM wallet_accounts a LEFT JOIN ledger_entries e ON e.account_id=a.id WHERE a.kind='WALLET' GROUP BY a.id;
